import { MeshStandardNodeMaterial, Color } from 'three/webgpu';
import { texture, uv, mul } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  const root = new Group();

  // Geometry
  const geometry = new PlaneGeometry(3, 0.4, 64, 64);
  // Material
  const material = new MeshStandardNodeMaterial();
  material.roughness = 0.6;
  material.metalness = 0.4;
  material.clearcoat = 0.15;
  material.clearcoatRoughness = 0.2;
  material.emissive = new Color('#ff2a38');
  material.emissiveIntensity = 0.4;

  // Textures (loaded asynchronously)
  let colorTexture = null;
  let depthTexture = null;

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    colorTexture = tex;
    material.map = tex;
    material.needsUpdate = true;
  });

  ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
    depthTexture = tex;
    const dispNode = mul(texture(tex, uv()), 0.2);
    material.displacementNode = dispNode;
    material.needsUpdate = true;
  });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Apply cinematic primitives
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (typeof ctx.primitives[prim.name] === 'function') {
        const instance = ctx.primitives[prim.name](root, prim.params || {});
        primitiveInstances.push(instance);
      }
    }
  }

  // Event handlers
  root.userData.handlers = {};

  // Hover rise‑in effect
  const originalY = 0;
  let hoverTl = null;
  root.userData.handlers.hover = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, {
      y: originalY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };
  // Optional leave to restore position
  root.userData.handlers.leave = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, {
      y: originalY,
      duration: 0.5,
      ease: 'power2.in',
    });
  };

  // Click emit
  root.userData.handlers.click = () => {
    ctx.emit('hub-pricing.select');
  };

  // Cleanup
  root.userData.cleanup = () => {
    // Primitive cleanups
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }
    // Kill any GSAP timelines
    if (hoverTl) hoverTl.kill();
    // Dispose Three.js resources
    geometry.dispose();
    material.dispose();
    if (colorTexture) colorTexture.dispose();
    if (depthTexture) depthTexture.dispose();
  };

  return root;
}
